package com.example.bodega.producto.controller;
import com.example.bodega.producto.dto.ProductoResponse; import com.example.bodega.producto.mapper.ProductoMapper; import com.example.bodega.producto.repository.ProductoRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/alertas") @RequiredArgsConstructor
public class AlertaStockController {private final ProductoRepository productos;@GetMapping("/stock-bajo") @PreAuthorize("hasRole('ADMIN')") public List<ProductoResponse> bajo(){return productos.findStockBajo().stream().map(ProductoMapper::toResponse).toList();}@GetMapping("/agotados") @PreAuthorize("hasRole('ADMIN')") public List<ProductoResponse> agotados(){return productos.findByActivoTrueAndStockActual(0).stream().map(ProductoMapper::toResponse).toList();}@GetMapping("/productos-disponibles") @PreAuthorize("hasAnyRole('ADMIN','CAJERO')") public List<ProductoResponse> disponibles(){return productos.findByActivoTrueAndStockActualGreaterThan(0).stream().map(ProductoMapper::toResponse).toList();}}
